contract InvMutTest {
    C c;

    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 betLimit, uint256 difficulty, uint256 wagerAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (wagerAmount)); require(wagerAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= wagerAmount);
        require(betLimit > 0);
        require(difficulty > 1);
        require(wagerAmount == betLimit);

        c.OpenToThePublic(); if (__ESBMC_reverted()) return;
        c.AdjustBetAmounts(betLimit); if (__ESBMC_reverted()) return;
        c.AdjustDifficulty(difficulty); if (__ESBMC_reverted()) return;

        uint256 before = c.ethBalance(); if (__ESBMC_reverted()) return;
        c.wager{value: wagerAmount}(); if (__ESBMC_reverted()) return;
        uint256 afterBal = c.ethBalance(); if (__ESBMC_reverted()) return;
        bool isPlayer = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;

        assert(isPlayer && afterBal == before + wagerAmount);
    }

    receive() external payable {}
}

