pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 betLimit, uint256 difficulty, uint256 wagerAmount) internal {
        wagerAmount = bound(wagerAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= wagerAmount);
        vm.assume(betLimit > 0);
        vm.assume(difficulty > 1);
        wagerAmount = betLimit;
        try c.OpenToThePublic() {} catch { return; }
        try c.AdjustBetAmounts(betLimit) {} catch { return; }
        try c.AdjustDifficulty(difficulty) {} catch { return; }
        uint256 before;
        try c.ethBalance() returns (uint256 __r) { before = __r; } catch { return; }
        try c.wager{value: wagerAmount}() {} catch { return; }
        uint256 afterBal;
        try c.ethBalance() returns (uint256 __r) { afterBal = __r; } catch { return; }
        bool isPlayer;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { isPlayer = __r; } catch { return; }
        assertTrue(isPlayer && afterBal == before + wagerAmount);
    }

    function testFuzz_run(uint256 betLimit, uint256 difficulty, uint256 wagerAmount) public {
        _run(betLimit, difficulty, wagerAmount);
    }

    receive() external payable {}
}
